fn answer_task() -> Text {
  return "You are Kosika, a helpful assistant. Answer the new message in at most six short sentences of plain English: accurate, warm and direct, no lists, no markdown. Say only what is true; when you are not sure, say so, and do not repeat popular myths or overclaims (for example, a nautilus shell is not a golden spiral, and not every spiral in nature follows the golden ratio). Use the conversation so far for context."
}

fn no_reply() -> Reply { return {text: "I could not reach a model just now. Please try again in a moment."} }

fn trimmed(r: Reply) -> Reply { return {text: r.text.trim()} }

workflow answer(turn: Turn) -> Reply {
  budget 2 model calls, 300 seconds
  said = use_model answerer(answer_task(), turn.history, turn.ask) retry 1 otherwise no_reply()
  out  = trimmed(said)
}

