// "notes/plan.md:12: text" names its own source: "notes/plan.md, line 12".
fn source_of(hit: Text) -> Text {
  let parts = hit.split(":")
  if parts.length() < 3 { return hit }
  return parts[0] + ", line " + parts[1]
}

// The program's own check of the model's answer, used by `verify`. It
// returns what is wrong, which is shown to the model, or "" when the answer
// may stand. An answer left empty is refused too, so that a fast model
// giving up is a reason to ask the strong one.
fn proven(found: Found, hits: Hits) -> Text {
  if found.answer.trim().length() == 0 { return "No answer was given. Answer from the lines and give an exact quote." }
  if found.quote.trim().length() < 6 { return "Give a quote of at least a few words copied from one line, or set answer and quote to \"\" if the lines do not answer." }
  if proof(hits, found.quote).length() == 0 { return "Your quote is not word for word in any of the lines. Copy the exact words from one line without changing them, and do not include the file name or line number. If the lines do not answer the question, set answer and quote to \"\"." }
  return ""
}

fn unproven(hits: Hits) -> Found {
  return {answer: "", quote: ""}
}

fn closest(hits: Hits) -> Text {
  return hits.matches.slice(0, hits.matches.length().min(5)).join("\n")
}

// "69.15%" or "3.1" in "x3.1"; empty when there is none.
fn number_text(text: Text) -> Text {
  var digits = ""
  for c in text.take(40).chars() {
    if "0123456789.,".contains(c) and not (digits.is_empty() and ".,".contains(c)) { digits = digits + c }
    else if not digits.is_empty() { return digits.trim_marks(".,") }
  }
  return digits.trim_marks(".,")
}

// A figure of numbers is kept only when each number is one the paper
// itself gives: it must be found, as written, in the text the model read.
// A model that makes a number up, or puts a name where the number goes,
// loses that figure.
fn grounded(figure: Figure, source: Text) -> Bool {
  return match figure.look {
    case "numbers" { (for item in figure.items where "0123456789x×~≈<>+-$".contains(item.label.trim().take(1).lower()) and not number_text(item.label).is_empty() and source.contains(number_text(item.label)) { item }).length() == figure.items.length() }
    case "bars" { (for item in figure.items where not number_text(item.value).is_empty() and source.contains(number_text(item.value)) { item }).length() == figure.items.length() }
    case _ { true }
  }
}

