fn child(e: Text[], which: Number) -> Text[] recurse 64 {
  let first = extent(e, 1)
  if which == 1 { return e.slice(1, 1 + first) }
  return e.slice(1 + first, 1 + first + extent(e, 1 + first))
}

fn is_const(e: Text[]) -> Bool { return e.length() == 1 and e[0].starts_with("n:") }
fn cval(e: Text[]) -> Number { return e[0].slice(2, e[0].length()).to_number().or(0) }

fn value_of(names: Text[], values: Number[], name: Text, at: Number) -> Number recurse 8 {
  if at >= names.length() { return 0 }
  if names[at] == name { return values[at] }
  return value_of(names, values, name, at + 1)
}

fn at(e: Text[], names: Text[], values: Number[]) -> Number recurse 64 {
  if is_const(e) { return cval(e) }
  if e.length() == 1 { return value_of(names, values, e[0], 0) }
  let op = e[0]
  if op == "~" { return -at(child(e, 1), names, values) }
  if op == "+" { return at(child(e, 1), names, values) + at(child(e, 2), names, values) }
  if op == "-" { return at(child(e, 1), names, values) - at(child(e, 2), names, values) }
  if op == "*" { return at(child(e, 1), names, values) * at(child(e, 2), names, values) }
  if op == "/" { return at(child(e, 1), names, values) / at(child(e, 2), names, values) }
  if op == "^" { return at(child(e, 1), names, values).power(at(child(e, 2), names, values)) }
  if op == "sin" { return at(child(e, 1), names, values).sin() }

