fn ordered(tasks: Task[]) -> Task[] {
  var out: Task[] = []
  for task in tasks { out = out.append(task.ranked()) }
  return out.sort_by(field: "rank")
}

fn open_tasks(tasks: Task[]) -> Task[] {
  var out: Task[] = []
  for task in tasks where not task.done { out = out.append(task) }
  return out
}

fn length_text(minutes: Number) -> Text {
  if minutes < 60 { return minutes.to_text() + "m" }
  let hours = (minutes / 60).floor()
  let rest = minutes - hours * 60
  return hours.to_text() + "h" + (if rest > 0 { " " + rest.to_text() + "m" } else { "" })
}

fn line_for(task: Task) -> Text {
  let mark = if task.priority == 3 { " !high" } else { if task.priority == 1 { " !low" } else { "" } }
  let due = if task.due.length() > 0 { ", due " + task.due } else { "" }
  let spent = if task.spent > 0 { ", " + length_text(task.spent) + " done" } else { "" }
  return task.title + mark + " (" + length_text(task.minutes) + due + spent + ")"
