// A quote without the marks around it. A model often ends a quote with a
// full stop where the line goes on with a comma. The words between must
// still be found exactly, so this forgives the ends and nothing else.
fn bare(quote: Text) -> Text {
  var text = quote.lower().trim()
  var trimming = true
  while trimming and text.length() > 0 {
    trimming = false
    for mark in [".", ",", ";", ":", "!", "?", "\"", "'"] {
      if text.ends_with(mark) {
        text = text.slice(0, text.length() - 1).trim()
        trimming = true
      }
      if text.starts_with(mark) {
        text = text.slice(1, text.length()).trim()
        trimming = true
      }
    }
  }
  return text
}

