// The functions and classes a Python file defines at its left margin.
fn defined(text: Text) -> Text[] {
  var names: Text[] = []
  for line in text.lines() {
    var rest = ""
    if line.starts_with("def ") { rest = line.drop(4) }
    else if line.starts_with("async def ") { rest = line.drop(10) }
    else if line.starts_with("class ") { rest = line.drop(6) }
    let name = rest.split("(").first().or("").split(":").first().or("").trim()
    if not name.is_empty() and not names.contains(name) { names = names.append(name) }
  }
  return names
}

