fn closest(at: Number[][]) -> Number {
  var best = 1000000
  for i in 0 until at[0].length() {
    for j in i + 1 until at[0].length() {
      let dx = at[0][i] - at[0][j]
      let dy = at[1][i] - at[1][j]
      best = best.min((dx * dx + dy * dy).sqrt())
    }
  }
  return best
}

