fn hierarchy_svg(s: Structure, at: Number[][]) -> Text {
  let mind = s.shape == "mindmap"
  let tops = for i in 0 until s.parts.length() where not s.parts[i].parent.is_empty() and s.parts[place(s, s.parts[i].parent)].parent.is_empty() { i }
  var edges: Text[] = []
  for i in 0 until s.parts.length() {
    let p = s.parts[i]
    if not p.parent.is_empty() {
      let a = place(s, p.parent)
      let ax = at[0][a]
      let ay = at[1][a]
      let bx = at[0][i]
      let by = at[1][i]
      let path = if mind { f"M{f1(ax)} {f1(ay)} Q{f1(ax + (bx - ax) * 0.15)} {f1(ay + (by - ay) * 0.85)} {f1(bx)} {f1(by)}" } else { f"M{f1(ax)} {f1(ay + 22)} C{f1(ax)} {f1((ay + by) / 2)} {f1(bx)} {f1((ay + by) / 2)} {f1(bx)} {f1(by - 22)}" }
      let colour = if mind { hue(tops.index_of(branch_of(s, i)).or(0)) } else { "" }
      edges = edges.append(edge_svg(f"l-{p.parent}-{p.id}", p.parent, p.id, path, "", 0, 0, colour))
    }
  }
  // In a mind map each idea's box takes its branch's colour.
  let nodes = for i in 0 until s.parts.length() { tinted(part_svg(s.parts[i], at[0][i], at[1][i]), if mind and not s.parts[i].parent.is_empty() { hue(tops.index_of(branch_of(s, i)).or(0)) } else { "" }) }
  return edges.join("") + nodes.join("")
}

