// The words of a question worth searching for: not the small words every
// question has. At most six, so the search stays sharp.
fn key_words(text: Text, skip_first: Bool) -> Text {
  let small = ["a", "an", "the", "is", "are", "was", "were", "be", "do", "does", "did", "i", "me", "my", "we", "our", "you", "your", "it", "its", "of", "in", "on", "at", "to", "for", "from", "by", "with", "about", "and", "or", "what", "when", "where", "which", "who", "whom", "why", "how", "tell", "say", "says", "said", "there", "that", "this", "these", "those", "have", "has", "had", "can", "could", "should", "would", "will", "please", "any", "all", "much", "many", "need", "find", "search", "show"]
  var words: Text[] = []
  var seen = false
  for word in text.words() {
    let item = clean(word)
    if item.length() > 0 {
      if (seen or not skip_first) and item.length() > 1 and not small.contains(item) and not words.contains(item) {
        words = words.append(item)
      }
      seen = true
    }
  }
  return words.take(6).join(" ")
}

