fn review_said(known: BooksRecalled) -> Said {
  let tasks = tasks_of(known)
  let open = open_tasks(tasks)
  var waiting = 0
  var logged = 0
  var high = 0
  for task in tasks { logged += task.spent }
  for task in open {
    waiting += (task.minutes - task.spent).max(0)
    if task.priority == 3 { high += 1 }
  }
  return {text: "Finished: " + (tasks.length() - open.length()) + " task(s).\nWaiting: " + open.length() + " task(s), about " + length_text(waiting) + " of work, " + high + " marked high.\nTime logged: " + length_text(logged) + "."}
}

