fn link_svg(s: Structure, l: Link, at: Number[][]) -> Text {
  let a = place(s, l.from)
  let b = place(s, l.to)
  let ax = at[0][a]
  let ay = at[1][a]
  let bx = at[0][b]
  let by = at[1][b]
  let dx = bx - ax
  let dy = by - ay
  let len = (dx * dx + dy * dy).sqrt().max(1)
  // Leave each box by its side when the link runs sideways, else by its top or bottom.
  let side = dx.abs() > dy.abs()
  let wa = box_width(s.parts[a]) / 2 + 6
  let wb = box_width(s.parts[b]) / 2 + 10
  let sx = if side { ax + wa * (if dx > 0 { 1 } else { -1 }) } else { ax }
  let sy = if side { ay } else { ay + 28 * (if dy > 0 { 1 } else { -1 }) }
  let ex = if side { bx - wb * (if dx > 0 { 1 } else { -1 }) } else { bx }
  let ey = if side { by } else { by - 32 * (if dy > 0 { 1 } else { -1 }) }
  // A link back to an earlier part bows out, so it never hides a forward one.
  let back = s.shape == "flow" and b < a
  let bow = if back { 90 } else { 0 }
  let c1x = if side { sx + (ex - sx) * 0.5 } else { sx + bow }
  let c1y = if side { sy - bow } else { sy + (ey - sy) * 0.5 }
  let c2x = if side { sx + (ex - sx) * 0.5 } else { ex + bow }
  let c2y = if side { ey - bow } else { sy + (ey - sy) * 0.5 }
  let mx = (sx + 3 * c1x + 3 * c2x + ex) / 8
  let my = (sy + 3 * c1y + 3 * c2y + ey) / 8
  let label = if l.label.is_empty() { "" } else { f"<text class=\"linklabel\" x=\"{f1(mx)}\" y=\"{f1(my - 7)}\">{escaped(l.label)}</text>" }
  let path = f"M{f1(sx)} {f1(sy)} C{f1(c1x)} {f1(c1y)} {f1(c2x)} {f1(c2y)} {f1(ex)} {f1(ey)}"

  max_steps: 1
}

