workflow answer(msg: Msg) -> Turn {
  turn = match is_open(msg) {
    case true { call answer_outside(msg) }
    case _ { call answer_here(msg) }
  }
}

workflow answer_here(msg: Msg) -> Turn {
  known  = recall books under "me"
  moment = now
  past   = recall talks under "me"
  first  = ask_prompt(msg, known, moment)
  prompt = with_talk(first, past)
  reply  = use_model voice(prompt.text) retry 1 otherwise {text: "Sorry, I could not think of an answer just now. Please ask again."}
  turn   = spoken(known, reply)
}

// A request for another agent is passed to it, and its answer passed back.
workflow pass_on(msg: Msg) -> Turn {
  known = recall books under "me"
  ask   = hand_of(msg.text)
  got   = execute desk.hand_over(ask.agent, ask.text) otherwise {ok: false, agent: "", text: "I have no way to reach the other agents from here. Open Kosika Studio and ask there."}
  turn  = handed_said(known, got)
}

