  let score = task.priority * 100 + urgency - task.minutes / 10
  let rank = (if task.done { 100000 } else { 0 }) - score
  return {title: task.title, priority: task.priority, minutes: task.minutes, due: task.due, done: task.done, spent: task.spent, rank: rank}
}

