// "tell the researcher to find my notes on trees", "@coder fix it", or
// "hand over: tidy my notes", which leaves the choice of agent to the app.
// What comes back has an empty text when it is no such request.
fn hand_of(said: Text) -> Handover {
  let tidy = said.trim()
  let lower = tidy.lower()
  let words = tidy.words()
  if lower.starts_with("@") and words.length() > 1 {
    return {agent: words[0].drop(1).trim_marks(":,").lower(), text: words.drop(1).join(" ")}
  }
  for lead in ["hand over:", "hand this over:", "pass this on:", "pass on:"] {
    if lower.starts_with(lead) { return {agent: "", text: tidy.drop(lead.length()).trim()} }
  }
  let asks = ["ask", "tell", "get", "have"].contains(words.first().or("").lower())
  if asks and words.length() > 4 and words[1].lower() == "the" and words[3].lower() == "to" {
    return {agent: words[2].lower(), text: words.drop(4).join(" ")}
  }
  return {agent: "", text: ""}
}

