fn reference_photo(p: Picture) -> Text {
  if p.image.is_empty() { return "" }
  return f"<figure class=\"ref bit\" id=\"photo\"><img src=\"{p.image}\" alt=\"{escaped(p.title)}\"><figcaption class=\"credit\">Real example: <a href=\"{p.page_url}\">{escaped(p.title)}</a> by {escaped(p.author)}, <a href=\"{p.license_url}\">{escaped(p.license)}</a>, Wikimedia Commons.</figcaption></figure>"
}

fn draw_page(r: Request) -> Text {
  let s = r.structure
  let golden = s.figure == "golden_spiral"
  let drawing = if golden { golden_svg(9) } else { structure_svg(s) }
  let sentences = if golden { golden_steps(9).join("") } else { (for i in 0 until s.steps.length() { step_line(i, shown_ids(s, s.steps[i]), "", escaped(s.steps[i].text)) }).join("") }
  let think = f"<div class=\"think\" id=\"think\" data-lines=\"{quoted(thinking(s))}\" data-done=\"Done. Hover a step to mark it again.\"></div>"
  return f"<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Kosika Designs</title><style>{draw_style()}{kinds_style()}</style></head><body><main><div class=\"brand\">Kosika Designs</div><div class=\"ask\">&#8220;{escaped(r.ask)}&#8221;</div><h1>{escaped(s.title)}</h1>{think}{drawing}<div class=\"hud\" id=\"hud\"></div><ol>{sentences}</ol>{reference_photo(r.picture)}<div class=\"bar\"><span class=\"credit\">{escaped(s.summary)}</span><button id=\"replay\" type=\"button\">Replay</button></div></main><script>{draw_script()}</script></body></html>"
}

workflow draw(r: Request) -> Design {
