  if found.answer.trim().is_empty() { return "No answer was given. Answer from the lines and give an exact quote." }
  if found.quote.trim().length() < 6 { return "Give a quote of at least a few words copied from one line, or set answer and quote to \"\" if the lines do not answer." }
  if proof(hits, found.quote).length() == 0 { return "Your quote is not word for word in any of the lines. Copy the exact words from one line without changing them, and do not include the file name or line number. If the lines do not answer the question, set answer and quote to \"\"." }
  return ""
}

fn unproven(hits: Hits) -> Found {
  return {answer: "", quote: ""}
}

fn closest(hits: Hits) -> Text {
  return hits.matches.slice(0, hits.matches.length().min(5)).join("\n")
}

fn answered(ask: Query, hits: Hits, found: Found) -> Said {
  if ask.query.length() == 0 {
    return {text: "Ask me something about the files, or say \"find\" and a few words."}
  }
  if hits.matches.length() == 0 {
    return {text: "I found nothing about \"" + ask.query + "\" in the folder. Try other words, or say \"find\" and a word you know is in the file."}
  }
  let hit = proof(hits, found.quote)
  if found.answer.trim().length() == 0 or hit.length() == 0 {
    return {text: "I will not guess: I could not back an answer with an exact quote. The closest lines I found for \"" + ask.query + "\" are:\n" + closest(hits)}
  }
  return {text: found.answer.trim() + "\nQuote: \"" + found.quote.trim() + "\"\nFrom: " + source_of(hit)}
}

