		outcome = scripted.answers[scripted.asked-1]
	} else if r.servers[tool.Source] != nil {
		outcome = r.callDeclaredTool(tool, arguments)
	} else {
		outcome = mockTool(tool)
	}
	r.validate(outcome, tool.Output, "$")
	return outcome
}

