// whole is one card among them, not a banner that outweighs the drawing.
fn photo_strip(s: Structure, photos: PartPhoto[], whole: Picture) -> Text {
  let shown = for ph in photos where not ph.picture.image.is_empty() and ids(s).contains(ph.part) { ph }
  if shown.is_empty() { return "" }
  let whole_name = whole.title.replace(" (Wikipedia)", "")
  let lead = if whole.image.is_empty() { "" } else { f"<figure class=\"pp whole\"><img src=\"{whole.image}\" alt=\"{escaped(whole.title)}\"><figcaption>{escaped(whole_name)}</figcaption></figure>" }
  let lead_credit = if whole.image.is_empty() { "" } else { f"<a href=\"{whole.page_url}\">{escaped(whole.title)}</a> by {escaped(whole.author)}, {escaped(whole.license)}; " }
  let cards = lead + (for ph in shown { f"<figure class=\"pp sym\" data-show=\"p-{ph.part}\"><img src=\"{ph.picture.image}\" alt=\"{escaped(ph.picture.title)}\"><figcaption>{escaped(s.parts[place(s, ph.part)].label)}</figcaption></figure>" }).join("")
  let credits = (for ph in shown { f"<a href=\"{ph.picture.page_url}\">{escaped(ph.picture.title)}</a> by {escaped(ph.picture.author)}, {escaped(ph.picture.license)}" }).join("; ")
  return f"<section class=\"strip bit\" id=\"strip\"><div class=\"plab\">Seen for real</div><div class=\"pps\">{cards}</div><p class=\"credit\">Photos from Wikimedia Commons: {lead_credit}{credits}.</p></section>"
}

