// The height of one row of a flow: room for its tallest column.
fn band_height(s: Structure) -> Number {
  let col = columns(s)
  var tallest = 1
  for c in col { tallest = tallest.max((for x in col where x == c { x }).length()) }
  return tallest * 96 + 84
}

fn height(s: Structure, w: Number) -> Number {
  if s.shape == "flow" { return ((columns(s).max().or(0) + 1) / per_row(s, w)).ceil() * band_height(s) }
  if s.shape == "layers" { return s.parts.length() * 76 + 40 }
  if ["tree", "mindmap", "graph", "timeline", "compare", "sketch"].contains(s.shape) { return kind_height(s) }
  return 480
}

