fn no_rule() -> Rule {
  return {text: ""}
}

// A rule worth keeping: its first line, not too short or long.
fn clean_rule(rule: Rule) -> Text {
  let line = rule.text.trim().lines().first().or("").trim().trim_marks("-*\"'`")
  return if line.length() < 12 or line.length() > 300 { "" } else { line }
}

fn rules_with(known: RulesRecalled, rule: Rule) -> Rules {
  let before = if known.found { known.value.value().items } else { [] }
  let line = clean_rule(rule)
  if line.is_empty() or before.contains(line) { return {items: before} }
  return {items: [line].concat(before).take(15)}
}

// The next try reads the newest rules too.
fn with_learned(last: Outcome, now: Rules) -> Outcome {
  let a = last.asked
  let learned = if now.items.is_empty() { a.learned } else { learned_words(now.items) }
  return {passed: last.passed, stage: last.stage, tries: last.tries, files: last.files, written: last.written, failed: last.failed, build: last.build, screen: last.screen, spec: last.spec, asked: {rules: a.rules, learned: learned, spec: a.spec, guides: a.guides, before: a.before, feedback: a.feedback}}
}

