fn timeline_layout(s: Structure, w: Number, h: Number) -> Number[][] {
  let n = s.parts.length()
  let xs = for i in 0 until n { 70 + (w - 140) * (if n == 1 { 0.5 } else { i / (n - 1) }) }
  let ys = for i in 0 until n { h / 2 }
  return [xs, ys]
}

// Columns side by side; each row under its column.
fn compare_layout(s: Structure, w: Number, h: Number) -> Number[][] {
  let n = s.parts.length()
  let cols = for i in 0 until n where s.parts[i].parent.is_empty() { i }
  var xs: Number[] = for i in 0 until n { 0 }
  var ys: Number[] = for i in 0 until n { 0 }
  for c in 0 until cols.length() {
    let x = (c + 0.5) * w / cols.length()
    xs = xs.set(cols[c], x)
    ys = ys.set(cols[c], 40)
    let rows = children(s, s.parts[cols[c]].id)
    for r in 0 until rows.length() {
      xs = xs.set(rows[r], x)
      ys = ys.set(rows[r], 110 + r * 62)
    }
  }
  return [xs, ys]
}

